import typing

MARKER = '@@SILICONDEVINE_ISSUE@@'


class ImportProblem(ValueError):
    def __init__(self, issue):
        self.issue = issue
        super().__init__(issue['message'])


def problem(code, title, message, *, schema=None, **extra):
    return ImportProblem(dict(code=code, title=title, message=message, severity='error', schema=schema, **extra))


def literal(value):
    if value is None or type(value) in (str, int, bool): return value
    if type(value) is float and math.isfinite(value): return value
    if isinstance(value, (list, tuple)): return [literal(v) for v in value]
    if isinstance(value, dict): return {str(k): literal(v) for k, v in value.items()}
    raise TypeError('not a literal')


def value_schema(value, depth=0):
    if depth > 5: return {'kind': 'any'}
    if isinstance(value,dict) and '$tensor' in value:return {'kind':'tensor'}
    if isinstance(value, dict) and '$class' in value: return {'kind': 'object', 'class': value['$class']}
    if isinstance(value, dict) and '$namespace' in value: return {'kind': 'namespace'}
    if isinstance(value, dict) and 'shape' in value: return {'kind': 'tensor'}
    if isinstance(value, dict): return {'kind': 'mapping', 'children': [dict(name=str(k), required=True, value=v, **value_schema(v, depth+1)) for k,v in value.items()]}
    if isinstance(value, list): return {'kind': 'sequence', 'children': [dict(name=str(i), required=True, value=v, **value_schema(v, depth+1)) for i,v in enumerate(value)]}
    return {'kind': 'boolean' if type(value) is bool else 'integer' if type(value) is int else 'number' if type(value) is float else 'text' if isinstance(value, str) else 'none' if value is None else 'any'}


def _annotation(annotation, namespace, depth):
    if isinstance(annotation, str):
        name=annotation.replace('typing.', '').replace('Optional[', '').removesuffix(']').split('|')[0].strip().strip("'\"")
        simple={'int':'integer','float':'number','bool':'boolean','str':'text','Tensor':'tensor','torch.Tensor':'tensor','Path':'text'}
        if name in simple: return {'kind':simple[name]}
        if name in namespace: annotation=namespace[name]
        else:
            try:
                expr=ast.parse(annotation,mode='eval').body
                if isinstance(expr,ast.Subscript) and ast.unparse(expr.value).endswith('Literal'):
                    values=ast.literal_eval(expr.slice)
                    return {'kind':'choice','choices':list(values) if isinstance(values,tuple) else [values]}
                if isinstance(expr,ast.Subscript):
                    container=ast.unparse(expr.value).split('.')[-1].lower()
                    if container in ('list','tuple','sequence'):return {'kind':'sequence'}
                    if container in ('dict','mapping'):return {'kind':'mapping'}
            except (SyntaxError,ValueError,TypeError): pass
            return {'kind':'any'}
    origin=typing.get_origin(annotation)
    if origin in (list,tuple):return {'kind':'sequence'}
    if origin is dict:return {'kind':'mapping'}
    if origin is typing.Literal: return {'kind':'choice','choices':list(typing.get_args(annotation))}
    if origin in (typing.Union,types.UnionType):
        options=[a for a in typing.get_args(annotation) if a is not type(None)]
        return {**_annotation(options[0],namespace,depth), 'nullable':True} if options else {'kind':'none'}
    simple={int:'integer',float:'number',bool:'boolean',str:'text',Path:'text',list:'sequence',tuple:'sequence',dict:'mapping'}
    if annotation in simple: return {'kind':simple[annotation]}
    if 'Tensor' in str(annotation): return {'kind':'tensor'}
    if inspect.isclass(annotation) and issubclass(annotation,enum.Enum):
        return {'kind':'enum','class':annotation.__module__+':'+annotation.__qualname__, 'choices':[m.name for m in annotation]}
    if depth<4 and inspect.isclass(annotation) and annotation.__module__ not in ('builtins','inspect'):
        return {'kind':'object','class':annotation.__module__+':'+annotation.__qualname__,
                'children':parameters(annotation,depth=depth+1)}
    return {'kind':'any'}


def parameters(callable_, *, values=None, forward=False, depth=0):
    values=values or {}
    try: signature=inspect.signature(callable_)
    except (TypeError,ValueError): return []
    module=inspect.getmodule(callable_);namespace=vars(module) if module else {}
    result=[]
    for p in signature.parameters.values():
        if p.name=='self' or p.kind in (p.VAR_POSITIONAL,p.VAR_KEYWORD): continue
        required=p.default is p.empty
        spec=_annotation(p.annotation,namespace,depth)
        value=values.get(p.name,p.default)
        item={'name':p.name,'required':required,'parameterKind':p.kind.name.lower(),
              'annotation':str(p.annotation) if p.annotation is not p.empty else '',**spec}
        if value is not p.empty:
            try:
                item['value']=literal(value)
                if spec['kind']=='any' and value is not None: item.update(value_schema(item['value']))
            except TypeError: item['defaultDescription']=repr(value)[:180]
        item['enabled']=p.name in values
        result.append(item)
    return result


def import_schema(selected, callable_=None, model=None, settings=None, report=None, inputs=None):
    settings=settings or {};data={'entry':selected['id'],'init':settings.get('init',{}),
        'seed':settings.get('seed',0),'backend':settings.get('backend','auto'),
        'max_parameters':settings.get('max_parameters',25_000_000)}
    for key in ('inputs','kwargs','ignore_project_config','input_mode'):
        if key in settings: data[key]=settings[key]
    forward=model.forward if model is not None else getattr(callable_,'forward',None)
    input_values=dict(settings.get('kwargs',{}))
    ps=[]
    if forward:
        try:
            ps=[p for p in inspect.signature(forward).parameters.values() if p.name!='self' and p.kind in (p.POSITIONAL_ONLY,p.POSITIONAL_OR_KEYWORD)]
            for p,v in zip(ps,settings.get('inputs',[])): input_values[p.name]=v
        except (TypeError,ValueError): pass
    if inputs and isinstance(inputs,list):
        for e in inputs:
            if isinstance(e,dict) and 'name' in e and 'input' in e: input_values.setdefault(e['name'],e['input'])
    elif isinstance(inputs,dict) and forward:
        input_values.update(inputs.get('kwargs',{}))
        for p,v in zip(ps,inputs.get('inputs',[])):input_values.setdefault(p.name,v)
    fields=parameters(forward,values=input_values,forward=True) if forward else []
    for f in fields:
        if f['name'] in input_values: f.update(value_schema(input_values[f['name']]), value=input_values[f['name']])
    return {'entry':selected['id'],'label':selected['name'],'settings':data,
            'candidates':[{k:c[k] for k in ('id','name','file','line')} for c in (report or {}).get('modules',[])],
            'constructor':parameters(callable_,values=data['init']) if callable_ else [],
            'inputs':fields,'hasForward':forward is not None}


def dependency_issue(name, sources=(), detail=''):
    top=(name or '未知模块').split('.')[0];local=False;requirements=[]
    for source in sources:
        p=Path(source).resolve();root=p if p.is_dir() else p.parent
        for base in [root,*list(root.parents)[:2]]:
            if (base/top).is_dir() or (base/(top+'.py')).is_file(): local=True
            path=base/'requirements.txt'
            if path.is_file() and str(path) not in requirements: requirements.append(str(path))
    code='import_path' if local else 'dependency_missing'
    message=(f'项目中的 {name} 未能导入。请选择包含该包的仓库根目录，并保留原有目录结构。' if local else
             f'当前 Python 环境找不到模块 {name}。可以切换到该项目原有的环境，或按项目依赖清单安装后重试。')
    # Only established, unambiguous distribution names get an individual command.
    packages={'torch':'torch','numpy':'numpy','scipy':'scipy','pandas':'pandas','nibabel':'nibabel','einops':'einops','transformers':'transformers','yaml':'PyYAML','PIL':'Pillow'}
    return {'code':code,'title':('项目导入路径不完整' if local else '缺少依赖 · '+top),
            'message':message,'severity':'error','module':name,'package':None if local else packages.get(top),
            'requirements':requirements[:3],'detail':detail,'schema':None}


def exception_issue(exc,sources=()):
    if isinstance(exc,ImportProblem): return exc.issue
    chain=exc
    while chain.__cause__ is not None: chain=chain.__cause__
    detail=''.join(traceback.format_exception(type(exc),exc,exc.__traceback__))[-14000:]
    if isinstance(chain,ModuleNotFoundError): return dependency_issue(chain.name,sources,detail)
    if isinstance(chain,ImportError):
        return dict(code='dependency_incompatible',title='依赖接口无法导入',message='当前环境的依赖版本或运行库与模型要求不一致。请切换到项目所用环境，并按仓库依赖清单核对版本。',severity='error',detail=detail,module=getattr(chain,'name',None),schema=None)
    if isinstance(chain,SyntaxError):
        return dict(code='syntax_error',title='Python 代码存在语法错误',message=f'{chain.msg}。修正代码并保存后会自动重试。',severity='error',
                    file=chain.filename,line=chain.lineno,detail=detail,schema=None)
    if isinstance(chain,FileNotFoundError):
        return dict(code='file_missing',title='找不到模型需要的文件',message=f'无法读取 {chain.filename or str(chain)}。检查权重、数据或配置路径后重试。',severity='error',detail=detail,schema=None)
    timeout=isinstance(exc,TimeoutError) or type(exc).__name__=='TimeoutExpired'
    return dict(code='capture_timeout' if timeout else 'capture_failed',title='模型捕获超时' if timeout else '模型尚未完成捕获',
                message='本次计算未在时间限制内完成。可以延长启动器的捕获时限，或缩小模型提供的研究配置。' if timeout else str(exc).split('\n')[0][:600],
                severity='error',detail=detail,schema=None)


def validate_settings(value):
    if not isinstance(value,dict): raise ValueError('导入设置必须由表单生成。')
    allowed={'entry','init','inputs','kwargs','seed','backend','max_parameters','ignore_project_config','input_mode'}
    if set(value)-allowed: raise ValueError('存在未支持的导入选项。')
    if 'entry' in value and (not isinstance(value['entry'],str) or not re.fullmatch(r'[\w.]+:[\w.]+',value['entry'])): raise ValueError('请选择列表中的模型入口。')
    for key in ('init','kwargs'):
        if key in value and not isinstance(value[key],dict): raise ValueError(key+' 必须是一组命名参数。')
    if 'inputs' in value and not isinstance(value['inputs'],list): raise ValueError('输入顺序无效。')
    if 'backend' in value and value['backend'] not in ('auto','fx','export','execution'): raise ValueError('请选择有效的捕获接口。')
    if 'input_mode' in value and value['input_mode'] not in ('auto','explicit'): raise ValueError('请选择有效的输入方式。')
    if 'ignore_project_config' in value and type(value['ignore_project_config']) is not bool: raise ValueError('旧配置选项无效。')
    for key in ('seed','max_parameters'):
        if key in value and (type(value[key]) is not int or value[key] < (1 if key=='max_parameters' else 0) or value[key]>2**53-1): raise ValueError('请为 '+key+' 输入有效整数。')
    count=0
    def check(v,depth=0):
        nonlocal count
        count+=1
        if count>20000 or depth>12: raise ValueError('参数结构过大，请减少嵌套或示例值。')
        if v is None or type(v) in (bool,str,int): return
        if type(v) is float and math.isfinite(v): return
        if isinstance(v,list):
            for c in v: check(c,depth+1)
            return
        if isinstance(v,dict):
            if 'shape' in v:
                shape=v['shape']
                if not isinstance(shape,list) or len(shape)>16 or any(type(d) is not int or d<1 for d in shape): raise ValueError('张量尺寸须为正整数；例如 1, 3, 32, 32。')
                if math.prod(shape)>2_000_000: raise ValueError('单个示例输入超过 200 万元素，请减小尺寸。')
            for k,c in v.items():
                if not isinstance(k,str): raise ValueError('参数名称必须是文字。')
                check(c,depth+1)
            return
        raise ValueError('参数类型无效。')
    check(value)
    return value
